    {
			return rowObject.getProbability();
		}
	}

	private class InterpretationTableColumn : AbstractDynamicTableColumn<FunctionStartRowObject, Interpretation, object> {

		/* @Override */
		public string getColumnName() {
			return "Interpretation";
		}

		/* @Override */
		public Interpretation getValue(FunctionStartRowObject rowObject, Settings settings,
				object data, ServiceProvider services)
    {
			return rowObject.getCurrentInterpretation();
		}
	}

	private class FallthroughTableColumn : AbstractDynamicTableColumn<FunctionStartRowObject, Boolean, object> {

		/* @Override */
		public string getColumnName() {
			return "Is Fallthrough Target";
		}

		/* @Override */
		public Boolean getValue(FunctionStartRowObject rowObject, Settings settings, object data,
				ServiceProvider services)
    {
			Instruction preInstr =
				program.getListing().getInstructionBefore(rowObject.getAddress());
			if (preInstr == null) {
				return false;
			}

			if (!preInstr.hasFallthrough()) {
				return false;
			}

			return preInstr.getFallThrough().equals(rowObject.getAddress());
		}

	}

	private class DataReferencesTableColumn : AbstractDynamicTableColumn<FunctionStartRowObject, Integer, object> {

		/* @Override */
